NOW = datetime(2026, 11, 14, 12, 0, 0, tzinfo=timezone.utc)


def qat(minutes: float) -> str:
    """at(), written for a query string (the + of the offset is %2B)."""
    return at(minutes).replace("+", "%2B")


def at(minutes: float) -> str:
    """An instant `minutes` from NOW, as Python writes it (isoformat)."""
    from datetime import timedelta
    return (NOW + timedelta(minutes=minutes)).isoformat()


