class FakeAuth:
    def authenticate(self, token):
        if token not in {f"tok-{k}" for k in TOKENS}:
            raise AuthError("token rejected")
        pid, kind = TOKENS[token[4:]]
        return Principal(pid, kind)


class FakeDirectory:
    def groups(self, principal):
        return set(GROUPS.get(principal, []))


class FakeOwnership:
    def apps(self, principal):
        return set(OWNS.get(principal, []))


def limits(tier="T1") -> dict:
    return {"tier_ceiling": tier, "ttl_minutes": 20, "tool_calls": 60, "github_calls": 40, "open_prs": 1, "model_tokens": 400000,
            "children": 0, "tools": ["repo.file.get"], "models": ["claude-sonnet-5-5"], "network": "clearance+model", "compute": "small"}


def sess(sid, principal, agent, task, created, expires, *, closed=False, outcome=None, parent=None, used=None, usage=None, run=None, inp=None):
    return {"id": sid, "principal": principal, "agent": agent, "limits": limits(), "created_at": at(created), "expires_at": at(expires),
            "parent_id": parent, "depth": 1 if parent else 0, "task_id": task,
            "used": used or {"tool_calls": 3, "github_calls": 1, "open_prs": 0, "model_tokens": 1200, "children": 0},
            "reserved": {"tool_calls": 0, "github_calls": 0, "open_prs": 0, "model_tokens": 0, "children": 0}, "children": [],
            "tripped": False, "trip_reason": None, "denials": 0, "closed": closed, "run": run, "input": inp, "outcome": outcome,
            "usage": usage or {"input_tokens": 100, "output_tokens": 20, "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0,
                               "charged_tokens": 120, "model_calls": 2},
            "signals": {}}


def sessions() -> list[dict]:
    out = [
        sess("s-001", "user:alice", "triage-agent", "t-1", -50, 10, run="r-aaaaaaaa", inp={"prompt": "why did gate-api fail?", "by": "user:alice"}),
        sess("s-002", "user:alice", "triage-agent", "t-1", -45, -5, closed=True, parent="s-001", outcome={"status": "ok", "turns": 3}),
        sess("s-003", "user:bob", "pin-a", "t-2", -40, 20),
        sess("s-004", "user:carol", "pin-b", "t-3", -300, -240),
        sess("s-005", "user:dave", "pin-a", "t-4", -35, 25, closed=True, outcome={"status": "failed", "reason": "boom"}),
        sess("s-006", "user:erin", "researcher", "t-5", -30, 30),
        sess("s-007", "agent-r-0123456789ab/run", "pin-b", "t-3", -299, -240, parent="s-004"),
    ]
    for i in range(8):   # a page's worth for the cursor
        out.append(sess(f"s-1{i:02d}", "user:alice", "triage-agent", f"t-9{i}", -20 + i, 40 + i))
    return out


