def drive(client, method, path, caller):
    tok, obo = CALLERS[caller]
    headers = {}
    if tok:
        headers["Authorization"] = f"Bearer tok-{tok}"
    if obo:
        headers["X-Hangar-On-Behalf-Of"] = obo
    r = client.request(method, path, headers=headers, follow_redirects=False)
    ct = r.headers.get("content-type")
    try:
        body = r.json() if "json" in (ct or "") else {"text": r.text}
    except ValueError:
        body = {"text": r.text}
    return {"status": r.status_code, "content_type": ct, "allow": r.headers.get("allow"), "location": r.headers.get("location"), "body": body}


def cases(data) -> list[dict]:
    app = app_for(data)
    out = []
    with TestClient(app, raise_server_exceptions=False) as client:
        for caller in CALLERS:
            for method, path in REQUESTS:
                ans = drive(client, method, path, caller)
                out.append({"name": f"{caller} {method} {path}", "caller": caller, "method": method, "path": path, "python": ans})
        for caller in ("admin", "anonymous", "alice"):
            for method, path in ODD:
                ans = drive(client, method, path, caller)
                out.append({"name": f"{caller} {method} {path}", "caller": caller, "method": method, "path": path, "python": ans})
    with TestClient(app_for(data, fail=True), raise_server_exceptions=False) as client:
        for caller in ("admin", "alice"):
            for method, path in [("GET", "/v1/sessions"), ("GET", "/v1/sessions/s-001"), ("GET", "/v1/events"), ("GET", "/v1/human/requests"),
                                 ("GET", "/v1/tasks/t-1"), ("GET", "/v1/agents"), ("GET", "/readyz"), ("GET", "/v1/runtimes")]:
                ans = drive(client, method, path, caller)
                out.append({"name": f"store-down {caller} {method} {path}", "caller": caller, "method": method, "path": path, "down": True, "python": ans})
    for c in out:
        py = c["python"]
        why = None
        if py["status"] == 307:
            c["go"] = {"status": 404, "content_type": "text/plain; charset=utf-8", "allow": None, "location": None, "body": {"text": "Not Found"}}
            why = "a trailing slash is not redirected: a redirect's Location is built from the Host header the caller sent"
        elif c.get("down") and py["status"] == 503 and isinstance(py["body"], dict) and str(py["body"].get("error", "")).startswith("read failed:"):
            c["go"] = {**py, "body": {"error": "read failed"}}
            why = "a failed read says only that it failed: the exception's class name is not for the caller"
        elif c.get("down") and c["path"] == "/readyz":
            c["go"] = {**py, "body": {"ok": False}}
            why = "the readiness failure does not name the exception's class"
        if why:
            c["why"] = why
    return out


def raw_cases() -> list[dict]:
    """Cursors and times the Python API passes to the database as they are: Python answers (or fails) as the database does; Go refuses
    anything that is not a time, with a 400, before it asks. The fake store has no database to refuse, so these are Go's alone and
    recorded here as Go-only cases, each with the reason."""
    return [
        {"name": "sessions after is not a cursor", "caller": "admin", "path": "/v1/sessions?after=%27%3B%20DROP%20TABLE%20x%3B--", "status": 400,
         "body": {"error": "after is a cursor from a previous page"},
         "why": "a cursor is a time the API itself wrote; Python hands any text to the database as a parameter"},
        {"name": "events after is not a cursor", "caller": "admin", "path": "/v1/events?after=garbage", "status": 400,
         "body": {"error": "after is a cursor from a previous page"},
         "why": "Python lets the database refuse it (a 503 read failure)"},
        {"name": "limit has an underscore", "caller": "admin", "path": "/v1/sessions?limit=1_0", "status": 400, "body": {"error": "limit must be a number"},
         "why": "Python's int() reads 1_0 as 10"},
        {"name": "limit is an arabic-indic digit", "caller": "admin", "path": "/v1/sessions?limit=%D9%A3", "status": 400, "body": {"error": "limit must be a number"},
         "why": "Python's int() reads any Unicode decimal digit"},
        {"name": "a very long query", "caller": "admin", "path": "/v1/sessions?x=" + "a" * 5000, "status": 414, "body": {"error": "the query string is too long"},
         "why": "Python/uvicorn accept it; the Go API bounds the request line"},
    ]


def build() -> str:
    data = seed()
    doc = {
        "now": NOW.isoformat(),
        "data": data,
        "directory": GROUPS, "ownership": OWNS, "tokens": {k: {"id": v[0], "kind": v[1]} for k, v in TOKENS.items()},
        "callers": {k: {"token": v[0], "on_behalf_of": v[1]} for k, v in CALLERS.items()},
        "config": {"delegates": DELEGATES, "auditors": AUDITORS, "notifiers": NOTIFIERS, "gateway_url": "http://autopilot.example.test",
                   "clearance_api_url": "http://clearance-api.example.test", "custom_images": ["ghcr.io/jfillman/app-*"]},
        "cases": cases(data),
        "go_only": raw_cases(),
    }
    return json.dumps(doc, sort_keys=True, ensure_ascii=False, separators=(",", ":")) + "\n"


# -- metrics -------------------------------------------------------------------------------------------------------------------

def metrics_doc() -> str:
    """The exposition of TriggerMetrics after scripts of calls (the same calls the Go test makes through triggers.Metrics)."""
    scripts = {
        "empty": [],
        "bridge": [("events_received", {"via": "stream"}, 1), ("events_received", {"via": "stream"}, 1), ("events_received", {"via": "recent"}, 1),
                   ("stream_connected", {}, 1), ("last_event", {}, 1731585600.0), ("cursor_time", {}, 1731585000.5),
                   ("resumes", {"result": "caught-up"}, 1), ("resumes", {"result": "stale-cursor"}, 1),
                   ("outcomes", {"agent": "triage-agent", "via": "stream", "result": "launched"}, 1),
                   ("outcomes", {"agent": "triage-agent", "via": "stream", "result": "deduped"}, 1),
                   ("outcomes", {"agent": "a\"b\\c\nd", "via": "reconcile", "result": "braked"}, 3),
                   ("missed", {"agent": "triage-agent", "result": "launched"}, 1), ("sweeps", {"result": "ok"}, 1), ("sweeps", {"result": "failed"}, 2),
                   ("sweep_ok", {}, 1731585700.0)],
        "scheduler": [("slot_launches", {"agent": "nightly-reviewer", "result": "launched"}, 1), ("slot_missed", {"agent": "nightly-reviewer"}, 2),
                      ("slot_lag", {"agent": "nightly-reviewer"}, 0.25), ("slot_lag", {"agent": "researcher"}, 12.0),
                      ("outcomes", {"agent": "x" * 200, "via": "schedule", "result": "launched"}, 1)],
        "gauge-reset": [("stream_connected", {}, 1), ("stream_connected", {}, 0), ("slot_lag", {"agent": "a"}, 1e-7), ("slot_lag", {"agent": "b"}, 123456789.0)],
    }
    out = {}
    for name, calls in scripts.items():
        m = mx.TriggerMetrics()
        attr = {"events_received": m.events_received, "stream_connected": m.stream_connected, "last_event": m.last_event,
                "cursor_time": m.cursor_time, "resumes": m.resumes, "outcomes": m.outcomes, "missed": m.missed, "sweeps": m.sweeps,
                "sweep_ok": m.sweep_ok, "slot_launches": m.slot_launches, "slot_missed": m.slot_missed, "slot_lag": m.slot_lag}
        for what, labels, value in calls:
            metric = attr[what]
            if isinstance(metric, mx.Counter):
                metric.inc(value, **labels)
            else:
                metric.set(value, **labels)
        out[name] = {"calls": [[w, l, v] for w, l, v in calls], "exposition": m.registry.render()}
    return json.dumps(out, indent=1, sort_keys=True) + "\n"


# -- OTLP logs -----------------------------------------------------------------------------------------------------------------

def otlp_doc() -> str:
    """The request body OTLPLogHandler posts, for records at each level, a long message and a formatted one; and the resource
    attributes resource_attributes() reads from environments."""
    sent = []
    h = otlp_logs.OTLPLogHandler("http://collector.test/v1/logs", {"service.name": "autopilot-api", "k8s.pod.name": "p-1"},
                                 post=lambda url, body, timeout: sent.append((url, body, timeout)) or 200, start=False)
    h.setLevel(logging.INFO)
    recs = []
    for lvl, msg, args in ((logging.DEBUG, "d", ()), (logging.INFO, "hello %s", ("world",)), (logging.WARNING, "careful", ()), (logging.ERROR, "bad", ()),
                           (logging.CRITICAL, "worse", ()), (logging.INFO, "abc " * 1250, ()), (logging.INFO, "naïve ☃ \"quoted\"", ())):
        r = logging.LogRecord("autopilot.api", lvl, __file__, 1, msg, args, None)
        r.created, r.threadName = 1731585600.123456, "MainThread"
        recs.append((lvl, msg, args, r))
        if lvl >= h.level:
            h.emit(r)
    h.flush_once()
    envs = {"none": {}, "service": {"OTEL_SERVICE_NAME": "svc"}, "attrs": {"OTEL_RESOURCE_ATTRIBUTES": "k8s.namespace.name=ns, k8s.pod.name=p ,bad,=x,y="},
            "attrs-service": {"OTEL_RESOURCE_ATTRIBUTES": "service.name=from-attrs,a=b"},
            "both": {"OTEL_SERVICE_NAME": "svc", "OTEL_RESOURCE_ATTRIBUTES": "service.name=from-attrs"}}
    doc = {"requests": [{"url": u, "body": json.loads(b), "raw": b.decode(), "timeout": t} for u, b, t in sent],
           "records": [{"level": r[0], "msg": r[1], "args": list(r[2]), "created": 1731585600.123456} for r in recs],
           "resources": {k: otlp_logs.resource_attributes(v, "autopilot-gateway") for k, v in envs.items()}, "envs": envs,
           "constants": {"queue_max": otlp_logs.QUEUE_MAX, "batch_max": otlp_logs.BATCH_MAX, "max_body": otlp_logs.MAX_BODY,
                         "severity": {str(k): v for k, v in otlp_logs.SEVERITY.items()}}}
    return json.dumps(doc, indent=1, sort_keys=True, ensure_ascii=False) + "\n"


def outputs() -> dict:
    return {OUT: build(), METRICS_OUT: metrics_doc(), OTLP_OUT: otlp_doc(),
            CONTRACT_OUT: json.dumps(read_api.contract(), indent=1) + "\n"}


if __name__ == "__main__":
    for p, t in outputs().items():
        p.parent.mkdir(parents=True, exist_ok=True)
        if "--check" in sys.argv:
            sys.exit(0 if p.is_file() and p.read_text() == t else 1)
        p.write_text(t)
